from __future__ import annotations


def desktop_html() -> str:
    return DESKTOP_HTML


def mobile_notification_html(notification_id: str) -> str:
    return MOBILE_NOTIFICATION_HTML.replace("__NOTIFICATION_ID__", notification_id)


def mobile_clue_html(clue_id: str) -> str:
    return MOBILE_CLUE_HTML.replace("__CLUE_ID__", clue_id)


def mobile_upload_html(case_id: str) -> str:
    return MOBILE_UPLOAD_HTML.replace("__CASE_ID__", case_id)


DESKTOP_HTML = """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>执行案件工作台</title><style>:root{--ink:#17211d;--muted:#65726d;--line:#d9e2de;--soft:#f6f8f7;--accent:#126b5d;--amber:#9a620f;--red:#a53c3c;--blue:#285f9d}*{box-sizing:border-box}body{margin:0;font-family:"Microsoft YaHei",system-ui,sans-serif;color:var(--ink);background:#fbfcfb;letter-spacing:0}button,input,select{font:inherit;letter-spacing:0}button{min-height:38px;border:1px solid var(--accent);background:var(--accent);color:#fff;border-radius:6px;padding:0 12px;cursor:pointer}button.secondary{background:#fff;color:var(--accent)}button.ghost{background:transparent;border-color:transparent;color:var(--muted)}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid #7bb7dc;outline-offset:2px}input,select{width:100%;min-height:38px;border:1px solid var(--line);border-radius:6px;background:#fff;padding:7px 9px}label{display:grid;gap:6px;font-size:13px;color:var(--muted)}a{color:var(--accent);text-decoration:none}header{height:58px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:20px;padding:0 20px;background:#fff;position:sticky;top:0;z-index:3}header strong{font-size:18px;white-space:nowrap}nav{display:flex;gap:4px;flex-wrap:wrap}nav button{min-height:34px;border-color:transparent;background:transparent;color:var(--muted)}nav button.active{background:#eaf3f0;color:var(--accent);border-color:#d1e5de}main{display:grid;grid-template-columns:292px minmax(0,1fr);min-height:calc(100vh - 58px)}aside{border-right:1px solid var(--line);background:#f7faf8;padding:16px;display:grid;gap:16px;align-content:start}section{padding:18px 22px 32px;min-width:0}h1{font-size:24px;margin:0 0 4px}h2{font-size:17px;margin:0 0 10px}h3{font-size:15px;margin:0 0 8px}p{margin:6px 0;color:var(--muted);line-height:1.55}.topline{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:16px}.toolbar,.controls{display:flex;gap:8px;flex-wrap:wrap;align-items:end}.controls{margin:0 0 10px}.controls label{width:160px}.panel-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:12px}.wide-grid{display:grid;grid-template-columns:2fr 1fr;gap:12px;margin-bottom:12px}.panel{border:1px solid var(--line);background:#fff;border-radius:8px;padding:14px;min-height:122px}.list{display:grid;gap:8px}.item{border:1px solid var(--line);background:#fff;border-radius:7px;padding:10px;min-width:0}.case-item{cursor:pointer}.case-item.active,.item.focused{border-color:var(--accent);box-shadow:0 0 0 2px rgba(18,107,93,.12)}.row{display:flex;align-items:center;justify-content:space-between;gap:10px}.meta{font-size:12px;color:var(--muted)}.badge{display:inline-flex;align-items:center;min-height:24px;border-radius:999px;padding:0 8px;background:#eef3f1;color:var(--muted);font-size:12px;white-space:nowrap}.badge.critical,.badge.high{background:#fff1dd;color:var(--amber)}.badge.medium{background:#eaf2ff;color:var(--blue)}.badge.red{background:#fff0f0;color:var(--red)}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.tabs{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0 14px}.tabs button{min-height:34px;background:#fff;color:var(--muted);border-color:var(--line)}.tabs button.active{background:#eaf3f0;color:var(--accent);border-color:#cfe2dd}.source{border-left:3px solid #cfe2dd;padding-left:10px;color:var(--muted);font-size:13px}.empty{color:var(--muted);border:1px dashed var(--line);border-radius:7px;padding:12px;background:#fbfcfb}.notice{min-height:24px;color:var(--accent);font-size:13px}.danger{color:var(--red)}.toast{position:fixed;right:20px;bottom:20px;max-width:360px;background:#fff;border:1px solid var(--line);border-radius:8px;padding:12px;box-shadow:0 8px 20px rgba(0,0,0,.12);z-index:20}pre{white-space:pre-wrap;word-break:break-word;margin:0;color:#26342e}@media(max-width:980px){main{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid var(--line)}.panel-grid,.wide-grid{grid-template-columns:1fr}.topline{display:grid}button{min-height:44px}.controls label{width:100%}}</style></head><body><header><strong>执行案件工作台</strong><nav id="nav"></nav></header><main><aside><div><div class="row"><h2>案件</h2><button class="ghost" onclick="renderHome()">首页</button></div><div id="caseList" class="list"></div></div><div class="panel"><h3>新建案件</h3><label>案件名称<input id="caseName" value="A 公司执行案件" oninput="saveDraft('newCase')"/></label><label>标的金额<input id="amount" type="number" value="1200000" oninput="saveDraft('newCase')"/></label><label>案由<input id="cause" value="买卖合同纠纷" oninput="saveDraft('newCase')"/></label><button onclick="createCase()">新建</button><div id="sideNotice" class="notice"></div></div></aside><section><div id="view"></div></section></main><script>
const baseHeaders={'Authorization':'Bearer user_owner','X-Tenant-Id':'tenant_demo','X-Client-Type':'web'};const jsonHeaders={...baseHeaders,'Content-Type':'application/json'};const params=new URLSearchParams(location.search);const state={selectedCase:params.get('case_id'),selectedSubject:null,workspace:null,activeTab:params.get('tab')||'overview',home:null,focus:{clue_id:params.get('clue_id'),event_id:params.get('event_id')},filters:{clueStatus:'all',clueSort:'value',materialStatus:'all',monitorStatus:'all',reportStatus:'all'},draftDirty:false};const $=id=>document.getElementById(id);function esc(value){return String(value??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}async function api(path,options={}){const res=await fetch(path,{...options,headers:{...jsonHeaders,...(options.headers||{})}});const body=await res.json().catch(()=>({}));if(!res.ok)throw new Error(body.error?.message||res.statusText);return body.data;}function empty(text){return `<div class="empty">${esc(text)}</div>`}function badge(text,kind=''){return `<span class="badge ${esc(kind)}">${esc(text)}</span>`}function toast(t,m){const old=document.querySelector('.toast');if(old)old.remove();const el=document.createElement('div');el.className='toast';el.innerHTML=`<strong>${esc(t)}</strong><div class="meta">${esc(m||'')}</div>`;document.body.appendChild(el);setTimeout(()=>el.remove(),4200)}function sourceBlock(refs){return (refs||[]).map(r=>`<div class="source">${esc(r.source_name)} · ${esc(r.source_time)}<br>${esc(r.snippet||'')}</div>`).join('')||'<div class="source">来源待补充</div>'}function setNav(active){const items=[['home','首页'],['cases','案件'],['materials','材料'],['clues','线索'],['monitor','监控'],['tasks','任务'],['reports','报告'],['settings','设置']];$('nav').innerHTML=items.map(([key,label])=>`<button class="${active===key?'active':''}" onclick="jump('${key}')">${label}</button>`).join('')}function saveDraft(scope){state.draftDirty=true;const data={caseName:$('caseName')?.value,amount:$('amount')?.value,cause:$('cause')?.value,subjectName:$('subjectName')?.value,tab:state.activeTab};localStorage.setItem(`lawUxDraft:${state.selectedCase||scope}`,JSON.stringify(data))}function restoreDraft(scope){try{const data=JSON.parse(localStorage.getItem(`lawUxDraft:${scope}`)||'{}');if(data.caseName&&$('caseName'))$('caseName').value=data.caseName;if(data.amount&&$('amount'))$('amount').value=data.amount;if(data.cause&&$('cause'))$('cause').value=data.cause;if(data.subjectName&&$('subjectName'))$('subjectName').value=data.subjectName}catch(e){}}window.addEventListener('beforeunload',e=>{if(state.draftDirty){e.preventDefault();e.returnValue=''}});async function loadCases(){const rows=await api('/api/cases');$('caseList').innerHTML=rows.map(c=>`<div class="item case-item ${state.selectedCase===c.id?'active':''}" onclick="openCase('${c.id}','overview')"><div class="row"><strong>${esc(c.case_name)}</strong>${badge(c.risk_level||'')}</div><div class="meta">${esc(c.stage||'执行中')}</div></div>`).join('')||empty('暂无案件');if(!state.selectedCase&&rows[0])state.selectedCase=rows[0].id}async function renderHome(){setNav('home');state.home=await api('/bff/home');const h=state.home;$('view').innerHTML=`<div class="topline"><div><h1>今日重点</h1><p>新线索、待确认报告、关键日期和待办事项集中处理。</p></div><div class="toolbar"><button onclick="openSelected()">进入案件</button><button class="secondary" onclick="renderHome()">刷新</button></div></div><div class="panel-grid">${metric('新增线索',h.summary.today_new_clue_count)}${metric('待确认报告',h.summary.pending_report_review_count)}${metric('监控异常',h.summary.monitor_exception_count)}</div><div class="wide-grid"><div class="panel"><h2>高价值线索</h2><div class="list">${h.high_value_clues.map(clueCard).join('')||empty('暂无线索')}</div></div><div class="panel"><h2>我的任务</h2><div class="list">${h.my_tasks.map(taskItem).join('')||empty('暂无任务')}</div></div></div><div class="panel-grid"><div class="panel"><h2>今日新增</h2><div class="list">${h.today_new_clues.map(simpleClue).join('')||empty('暂无新增')}</div></div><div class="panel"><h2>关键日期</h2><div class="list">${h.upcoming_deadlines.map(deadlineItem).join('')||empty('暂无日期')}</div></div><div class="panel"><h2>待确认报告</h2><div class="list">${h.pending_report_reviews.map(reportItem).join('')||empty('暂无报告')}</div></div></div>`}function metric(label,value){return `<div class="panel"><div class="meta">${esc(label)}</div><h1>${esc(value)}</h1></div>`}function simpleClue(x){return `<div class="item ${state.focus.clue_id===x.id?'focused':''}"><div class="row"><strong>${esc(x.title)}</strong>${badge(x.importance_label,x.importance)}</div><p>${esc(x.recommended_action)}</p></div>`}function clueCard(x){return `<div class="item ${state.focus.clue_id===x.id?'focused':''}"><div class="row"><strong>${esc(x.title)}</strong>${badge(x.importance_label,x.importance)}</div><p><strong>为什么重要：</strong>${esc(x.why_important)}</p><p><strong>下一步：</strong>${esc(x.recommended_action)}</p>${sourceBlock(x.source_refs)}<div class="actions"><button onclick="reviewClue('${x.id}','confirmed')">确认</button><button class="secondary" onclick="reviewClue('${x.id}','rejected')">忽略</button><button class="secondary" onclick="reviewClue('${x.id}','pending','create_task')">转任务</button><a class="meta" href="${esc(x.mobile_url)}">移动详情</a></div></div>`}function taskItem(x){return `<div class="item"><strong>${esc(x.title)}</strong><div class="meta">${esc(x.case_name)} · ${esc(x.status_label)}</div></div>`}function deadlineItem(x){return `<div class="item"><strong>${esc(x.date)}</strong><div class="meta">${esc(x.case_name)} · ${esc(x.title)}</div></div>`}function reportItem(x){return `<div class="item"><strong>${esc(x.title)}</strong><div class="meta">${esc(x.status_label)}</div></div>`}async function openSelected(){if(state.selectedCase)await openCase(state.selectedCase,'overview')}async function openCase(caseId,tab='overview'){if(state.selectedCase!==caseId)state.selectedSubject=null;state.selectedCase=caseId;state.activeTab=tab;setNav(tab==='overview'?'cases':tab);await loadCases();state.workspace=await api(`/bff/cases/${caseId}/workspace`);renderWorkspace();restoreDraft(caseId)}function jump(key){if(key==='home'){renderHome();return}if(!state.selectedCase){renderHome();return}const tabMap={cases:'overview',materials:'materials',clues:'clues',monitor:'monitor',tasks:'overview',reports:'reports',settings:'settings'};openCase(state.selectedCase,tabMap[key]||'overview')}function renderWorkspace(){const d=state.workspace,tab=state.activeTab;$('view').innerHTML=`<div class="topline"><div><h1>${esc(d.case.case_name)}</h1><p>${esc(d.case.stage_label)} · ${esc(d.case.risk_label)} · 标的金额 ${esc(d.case.amount)}</p></div><div class="toolbar"><label style="width:220px">主体名称<input id="subjectName" value="某某科技有限公司" oninput="saveDraft('case')"/></label><button onclick="resolveSubject()">确认主体</button><button onclick="generateReport()">生成报告</button><button class="secondary" onclick="createMonitor()">加入监控</button></div></div><div class="toolbar"><input id="fileInput" type="file" accept="image/*,.pdf,.doc,.docx,.txt"/><select id="sensitivity"><option>L2</option><option>L3</option><option>L4</option></select><button class="secondary" onclick="uploadFile()">上传材料</button><a class="meta" href="${esc(d.materials.mobile_upload_url)}">移动上传</a><span id="mainNotice" class="notice"></span></div><div class="tabs">${d.tabs.map(t=>`<button class="${tab===t.key?'active':''}" onclick="state.activeTab='${t.key}';saveDraft('case');renderWorkspace()">${esc(t.label)}</button>`).join('')}</div>${renderTab(d,tab)}`;restoreDraft(state.selectedCase)}function controls(scope){return `<div class="controls"><label>筛选<select onchange="state.filters.${scope}Status=this.value;renderWorkspace()"><option value="all">全部</option><option value="pending">待确认</option><option value="needs_review">需校对</option><option value="done">已处理</option></select></label><label>排序<select onchange="state.filters.${scope}Sort=this.value;renderWorkspace()"><option value="value">价值</option><option value="time">时间</option><option value="status">状态</option></select></label></div>`}function filterSortClues(rows){let out=[...rows];const f=state.filters.clueStatus;if(f==='pending')out=out.filter(x=>x.review_status==='pending');if(f==='done')out=out.filter(x=>x.review_status!=='pending');if(f==='needs_review')out=out.filter(x=>x.confidence_label==='需重点核验');const s=state.filters.clueSort;out.sort((a,b)=>s==='time'?String(b.created_at||'').localeCompare(String(a.created_at||'')):s==='status'?String(a.review_status_label).localeCompare(String(b.review_status_label)):(b.score||0)-(a.score||0));return out}function filterMaterials(rows){let out=[...rows];const f=state.filters.materialStatus;if(f==='needs_review'||f==='pending')out=out.filter(x=>x.low_confidence_count>0);if(f==='done')out=out.filter(x=>!x.low_confidence_count);return out.sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')))}function filterEvents(rows){let out=[...rows];const f=state.filters.monitorStatus;if(f==='pending')out=out.filter(x=>x.action_status==='unread');if(f==='done')out=out.filter(x=>x.action_status!=='unread');return out.sort((a,b)=>String(b.detected_at||'').localeCompare(String(a.detected_at||'')))}function filterReports(rows){let out=[...rows];const f=state.filters.reportStatus;if(f==='pending')out=out.filter(x=>x.status==='review_required');if(f==='done')out=out.filter(x=>x.status==='confirmed');return out.sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')))}function renderTab(d,tab){if(tab==='materials'){const rows=filterMaterials(d.materials.files);return `<div class="wide-grid"><div class="panel"><h2>材料</h2>${controls('material')}<div class="list">${rows.map(fileItem).join('')||empty('暂无材料')}</div></div><div class="panel"><h2>待校对内容</h2><div class="list">${rows.flatMap(f=>f.review_items||[]).map(blockItem).join('')||empty('暂无待校对内容')}</div></div></div>`}if(tab==='clues'){const rows=filterSortClues(d.clues.items);return `<div class="panel"><h2>线索</h2>${controls('clue')}<div class="list">${rows.map(clueCard).join('')||empty('暂无线索')}</div></div>`}if(tab==='monitor'){const events=filterEvents(d.monitor.events);return `<div class="wide-grid"><div class="panel"><h2>监控对象</h2><div class="list">${d.monitor.targets.map(targetItem).join('')||empty('暂无监控对象')}</div><h2 style="margin-top:14px">推送记录</h2><div class="list">${(d.monitor.delivery_records||[]).map(deliveryItem).join('')||empty('暂无推送记录')}</div></div><div class="panel"><h2>监控动态</h2>${controls('monitor')}<div class="list">${events.map(eventItem).join('')||empty('暂无动态')}</div></div></div>`}if(tab==='reports'){const rows=filterReports(d.reports.items);return `<div class="wide-grid"><div class="panel"><h2>报告</h2>${controls('report')}<div class="list">${rows.map(reportCard).join('')||empty('暂无报告')}</div></div><div class="panel"><h2>导出记录</h2><div class="list">${(d.reports.export_records||[]).map(exportItem).join('')||empty('暂无导出记录')}</div></div></div>`}if(tab==='settings')return `<div class="panel-grid"><div class="panel"><h2>主体</h2><div class="list">${d.settings.subjects.map(s=>`<div class="item"><strong>${esc(s.name)}</strong><div class="meta">${esc(s.review_status_label)}</div></div>`).join('')||empty('暂无主体')}</div></div><div class="panel"><h2>访问人员</h2><div class="list">${(d.settings.access_users||[]).map(u=>`<div class="item"><strong>${esc(u.name)}</strong><div class="meta">${esc(u.role)} · ${esc(u.access_label)}</div></div>`).join('')||empty('暂无人员')}</div></div><div class="panel"><h2>近期留痕</h2><div class="list">${(d.settings.recent_audit_logs||[]).map(a=>`<div class="item"><strong>${esc(a.action)}</strong><div class="meta">${esc(a.actor_name)} · ${esc(a.created_at)}</div></div>`).join('')||empty('暂无留痕')}</div></div></div><div class="panel-grid"><div class="panel"><h2>来源授权</h2><p>授权来源和人工补录状态由管理员维护。</p></div><div class="panel"><h2>提醒渠道</h2><p>站内、飞书、企业微信和邮件用于送达提醒。</p></div><div class="panel"><h2>测试状态</h2><p>体验测试未测试。</p></div></div>`;return `<div class="panel-grid"><div class="panel"><h2>今日重点</h2><div class="list">${d.overview.today_highlights.map(x=>x.next_action_url?clueCard(x):eventItem(x)).join('')||empty('暂无重点')}</div></div><div class="panel"><h2>待确认</h2><div class="list">${d.overview.pending_reviews.map(x=>`<div class="item"><strong>${esc(x.title)}</strong><div class="meta">${esc(x.status_label)}</div></div>`).join('')||empty('暂无待确认')}</div></div><div class="panel"><h2>任务</h2><div class="list">${d.overview.tasks.map(taskItem).join('')||empty('暂无任务')}</div></div></div><div class="panel-grid"><div class="panel"><h2>关键日期</h2><div class="list">${d.overview.upcoming_deadlines.map(deadlineItem).join('')||empty('暂无日期')}</div></div><div class="panel"><h2>风险</h2><div class="list">${d.overview.risks.map(x=>`<div class="item"><strong>${esc(x.title)}</strong><p>${esc(x.recommended_action)}</p></div>`).join('')||empty('暂无风险')}</div></div><div class="panel"><h2>案件要素</h2><pre>${esc(JSON.stringify(d.overview.extracted_summary||{},null,2))}</pre></div></div>`}function fileItem(x){return `<div class="item"><div class="row"><strong>${esc(x.name)}</strong>${badge(x.status_label,x.low_confidence_count?'red':'')}</div><div class="meta">${esc(x.source_channel)} · ${esc(x.sensitivity_level||'')}</div>${x.key_dates?.length?`<p>关键日期：${x.key_dates.map(d=>esc(d.value)).join('；')}</p>`:''}<div class="source">${esc((x.parsed_blocks||[])[0]?.text||'暂无解析文本预览')}</div></div>`}function blockItem(x){return `<div class="item"><strong>${esc(x.label)}</strong><p>${esc(x.text)}</p><div class="meta">${esc(x.review_status_label)}</div><div class="actions"><button class="secondary" onclick="reviewBlock('${x.id}')">标记已校对</button></div></div>`}function targetItem(x){return `<div class="item"><strong>${esc(x.subject_name)}</strong><div class="meta">${esc(x.frequency)} · ${esc((x.notify_channels||[]).join('、'))}</div></div>`}function eventItem(x){return `<div class="item ${state.focus.event_id===x.id?'focused':''}"><div class="row"><strong>${esc(x.title)}</strong>${badge(x.action_status_label,x.importance)}</div><p>${esc(x.recommended_action)}</p>${sourceBlock(x.source_refs)}<div class="actions"><button onclick="handleEvent('${x.id}','ack')">确认</button><button class="secondary" onclick="handleEvent('${x.id}','ignore')">忽略</button><button class="secondary" onclick="handleEvent('${x.id}','convert-to-task')">转任务</button></div></div>`}function deliveryItem(x){return `<div class="item"><strong>${esc(x.channel)}</strong><div class="meta">${esc(x.delivery_status)} · ${esc(x.created_at||'')}</div>${x.deep_link?`<a class="meta" href="${esc(x.deep_link)}">打开提醒</a>`:''}</div>`}function reportCard(x){return `<div class="item"><div class="row"><strong>${esc(x.title)}</strong>${badge(x.status_label,x.status==='review_required'?'red':'')}</div><div class="meta">${esc(x.created_at||'')}</div><div class="actions"><button onclick="reviewReport('${x.id}','confirmed')">确认报告</button><button class="secondary" onclick="reviewReport('${x.id}','rejected')">驳回并填写原因</button><a class="meta" href="${esc(x.export_urls?.md||'#')}">导出文本</a><a class="meta" href="${esc(x.export_urls?.html||'#')}">导出网页</a></div></div>`}function exportItem(x){return `<div class="item"><strong>${esc(x.format)}</strong><div class="meta">${esc(x.exported_by)} · ${esc(x.created_at)}</div></div>`}async function createCase(){if(!confirm('确认新建该案件？'))return;const payload={case_name:$('caseName').value,amount:Number($('amount').value),cause_of_action:$('cause').value};const created=await api('/api/cases',{method:'POST',body:JSON.stringify(payload)});state.draftDirty=false;localStorage.removeItem('lawUxDraft:newCase');state.selectedCase=created.id;$('sideNotice').textContent='案件已创建';await openCase(created.id,'overview')}async function resolveSubject(){const name=$('subjectName')?.value||'';if(!state.selectedCase||!name)return;const data=await api('/api/subjects/resolve',{method:'POST',body:JSON.stringify({case_id:state.selectedCase,name})});state.selectedSubject=data.candidates?.[0]?.subject_id;$('mainNotice').textContent='主体已确认';saveDraft('case')}async function ensureSubject(){if(!state.selectedSubject)await resolveSubject()}async function generateReport(){await ensureSubject();if(!state.selectedSubject)return;if(!confirm('确认生成资产线索报告？报告生成后会进入待律师确认。'))return;$('mainNotice').textContent='报告已提交，完成后进入待确认';await api(`/api/cases/${state.selectedCase}/asset-clue-reports`,{method:'POST',body:JSON.stringify({subject_id:state.selectedSubject,connector_ids:['manual_company_connector','execution_public_connector','public_auction_connector']})});await openCase(state.selectedCase,'reports')}async function createMonitor(){await ensureSubject();if(!state.selectedSubject)return;if(!confirm('确认将该主体加入监控？后续新动态会推送提醒。'))return;await api('/api/monitor-targets',{method:'POST',body:JSON.stringify({case_id:state.selectedCase,subject_id:state.selectedSubject,event_types:['new_execution','new_auction'],notify_channels:['in_app']})});await openCase(state.selectedCase,'monitor')}async function uploadFile(){const input=$('fileInput');if(!state.selectedCase||!input.files[0])return;const form=new FormData();form.append('file',input.files[0]);form.append('file_type','other');form.append('sensitivity_level',$('sensitivity').value);$('mainNotice').textContent='正在整理材料，完成后会进入待校对';const res=await fetch(`/api/cases/${state.selectedCase}/files`,{method:'POST',headers:baseHeaders,body:form});$('mainNotice').textContent=res.ok?'材料已收到，整理完成后会提醒你校对重点内容':'上传失败，请稍后重试';await openCase(state.selectedCase,'materials')}async function reviewClue(id,status,nextAction){let comment=null;if(status==='rejected'){comment=prompt('请填写忽略原因，便于后续复盘：')||'';if(!comment)return}else if(nextAction==='create_task'){if(!confirm('确认将该线索转为任务？'))return}else if(status==='confirmed'&&!confirm('确认该线索可进入后续处理？'))return;await api(`/api/asset-clues/${id}/review`,{method:'POST',body:JSON.stringify({review_status:status,next_action:nextAction||null,comment})});toast('处理完成','线索状态已更新');if(state.selectedCase)await openCase(state.selectedCase,state.activeTab);else await renderHome()}async function reviewReport(id,status){let comment=null;if(status==='rejected'){comment=prompt('请填写驳回原因：')||'';if(!comment)return}else if(!confirm('确认该报告？'))return;await api(`/api/reports/${id}/review`,{method:'POST',body:JSON.stringify({review_status:status,comment})});toast('处理完成','报告状态已更新');await openCase(state.selectedCase,'reports')}async function reviewBlock(id){if(!confirm('确认该内容已经校对？'))return;await api(`/api/document-blocks/${id}/review`,{method:'POST',body:JSON.stringify({review_status:'confirmed'})});toast('处理完成','材料内容已标记校对');await openCase(state.selectedCase,'materials')}async function handleEvent(id,action){const label={ack:'确认该提醒？',ignore:'忽略该提醒？','convert-to-task':'转为任务？'}[action]||'确认操作？';if(!confirm(label))return;await api(`/api/monitor-events/${id}/${action}`,{method:'POST'});toast('处理完成','提醒状态已更新');await openCase(state.selectedCase,'monitor')}async function boot(){setNav('home');restoreDraft('newCase');await loadCases();if(params.get('case_id'))await openCase(params.get('case_id'),state.activeTab);else await renderHome()}boot().catch(err=>{$('view').innerHTML=`<div class="empty danger">${esc(err.message)}</div>`});
</script></body></html>"""
MOBILE_NOTIFICATION_HTML = """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>提醒详情</title><style>body{margin:0;font-family:"Microsoft YaHei",system-ui,sans-serif;background:#fbfcfb;color:#17211d}main{max-width:520px;margin:0 auto;padding:18px}h1{font-size:22px;margin:8px 0 10px;letter-spacing:0}.meta{font-size:13px;color:#66736d}.box{border:1px solid #d9e2de;background:white;border-radius:8px;padding:14px;margin:10px 0}button{width:100%;min-height:46px;border:1px solid #126b5d;border-radius:7px;background:#126b5d;color:white;font-size:16px;margin:6px 0}button.secondary{background:white;color:#126b5d}.source{border-left:3px solid #cfe2dd;padding-left:10px;color:#66736d}</style></head><body><main><div class="meta" id="caseName">今日提醒</div><h1 id="title">提醒详情</h1><div class="box"><strong>为什么重要</strong><p id="why"></p></div><div class="box"><strong>来源</strong><div id="source" class="source"></div></div><div class="box"><strong>下一步</strong><p id="action"></p><div class="meta" id="status"></div></div><button onclick="handle('ack')">确认</button><button class="secondary" onclick="handle('ignore')">忽略</button><button class="secondary" onclick="handle('convert-to-task')">转任务</button><button class="secondary" onclick="openDesktop()">打开案件工作台</button></main><script>const notificationId="__NOTIFICATION_ID__";const headers={'Authorization':'Bearer user_owner','X-Tenant-Id':'tenant_demo','X-Client-Type':'mobile_h5','Content-Type':'application/json'};let eventId=null,desktopUrl='/';function esc(v){return String(v??'').replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]));}async function load(){const res=await fetch(`/bff/mobile/notifications/${notificationId}`,{headers});const body=await res.json();const data=body.data;eventId=data.event_id;desktopUrl=data.desktop_restore_url||`/?case_id=${data.case_id}&tab=monitor&event_id=${data.event_id}`;caseName.textContent=data.case_name||'今日提醒';title.textContent=data.title;why.textContent=data.why_important;action.textContent=data.recommended_action;status.textContent=data.action_status_label;source.innerHTML=(data.source_refs||[]).map(x=>`${esc(x.source_name)} · ${esc(x.source_time)}<br>${esc(x.snippet||'')}`).join('<br>')||'来源待补充';}async function handle(actionName){if(!confirm('确认处理该提醒？'))return;await fetch(`/api/monitor-events/${eventId}/${actionName}`,{method:'POST',headers});await load();}function openDesktop(){location.href=desktopUrl}load();</script></body></html>"""

MOBILE_CLUE_HTML = """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>线索详情</title><style>body{margin:0;font-family:"Microsoft YaHei",system-ui,sans-serif;background:#fbfcfb;color:#17211d}main{max-width:520px;margin:0 auto;padding:18px}h1{font-size:22px;margin:8px 0 10px;letter-spacing:0}.meta{font-size:13px;color:#66736d}.box{border:1px solid #d9e2de;background:white;border-radius:8px;padding:14px;margin:10px 0}.badge{display:inline-flex;align-items:center;min-height:24px;border-radius:999px;padding:0 8px;background:#fff1dd;color:#9a620f;font-size:12px}button{width:100%;min-height:46px;border:1px solid #126b5d;border-radius:7px;background:#126b5d;color:white;font-size:16px;margin:6px 0}button.secondary{background:white;color:#126b5d}ul{padding-left:20px}</style></head><body><main><div class="meta" id="caseName">线索详情</div><h1 id="title"></h1><div id="importance" class="badge"></div><div class="box"><strong>为什么重要</strong><p id="why"></p></div><div class="box"><strong>来源</strong><p id="source"></p></div><div class="box"><strong>建议动作</strong><p id="action"></p></div><div class="box"><strong>核验项</strong><ul id="checks"></ul></div><button onclick="review('confirmed')">确认</button><button class="secondary" onclick="review('rejected')">忽略并填写原因</button><button class="secondary" onclick="review('pending','create_task')">转任务</button><button class="secondary" onclick="review('pending','create_task','分享给负责人处理')">分享给负责人</button><button class="secondary" onclick="openDesktop()">打开案件工作台</button></main><script>const clueId="__CLUE_ID__";const headers={'Authorization':'Bearer user_owner','X-Tenant-Id':'tenant_demo','X-Client-Type':'mobile_h5','Content-Type':'application/json'};let desktopUrl='/';function esc(v){return String(v??'').replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]));}async function load(){const res=await fetch(`/bff/mobile/clues/${clueId}`,{headers});const body=await res.json();const data=body.data;desktopUrl=data.desktop_restore_url||`/?case_id=${data.case_id}&tab=clues&clue_id=${clueId}`;caseName.textContent=data.case_name;title.textContent=data.title;importance.textContent=data.importance_label;why.textContent=data.why_important;source.textContent=data.source_summary;action.textContent=data.recommended_action;checks.innerHTML=(data.verification_items||[]).map(x=>`<li>${esc(x)}</li>`).join('');}async function review(status,nextAction,comment){let finalComment=comment||null;if(status==='rejected'){finalComment=prompt('请填写忽略原因：')||'';if(!finalComment)return}else if(!confirm('确认处理该线索？'))return;await fetch(`/api/asset-clues/${clueId}/review`,{method:'POST',headers,body:JSON.stringify({review_status:status,next_action:nextAction||null,comment:finalComment})});await load();}function openDesktop(){location.href=desktopUrl}load();</script></body></html>"""

MOBILE_UPLOAD_HTML = """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>上传材料</title><style>body{margin:0;font-family:"Microsoft YaHei",system-ui,sans-serif;background:#fbfcfb;color:#17211d}main{max-width:520px;margin:0 auto;padding:18px}h1{font-size:22px;margin:8px 0 10px;letter-spacing:0}label{display:grid;gap:6px;margin:12px 0;color:#66736d}input,select{min-height:44px;border:1px solid #d9e2de;border-radius:7px;padding:8px;background:white}button{width:100%;min-height:46px;border:1px solid #126b5d;border-radius:7px;background:#126b5d;color:white;font-size:16px;margin:8px 0}.box{border:1px solid #d9e2de;background:white;border-radius:8px;padding:14px;margin:10px 0}.meta{font-size:13px;color:#66736d}</style></head><body><main><div class="meta" id="caseMeta">移动上传</div><h1>上传材料</h1><div class="box" id="copy">上传后会开始整理材料，完成后提醒你校对重点内容。</div><label>选择材料<input id="fileInput" type="file" accept="image/*,.pdf,.doc,.docx,.txt"/></label><label>材料类型<select id="fileType"><option value="other">案件材料</option><option value="judgment">裁判文书</option><option value="evidence">证据材料</option></select></label><label>敏感等级<select id="sensitivity"><option>L2</option><option>L3</option><option>L4</option></select></label><button onclick="upload()">上传</button><div id="status" class="meta"></div></main><script>const caseId="__CASE_ID__";const baseHeaders={'Authorization':'Bearer user_owner','X-Tenant-Id':'tenant_demo','X-Client-Type':'mobile_h5'};const jsonHeaders={...baseHeaders,'Content-Type':'application/json'};async function load(){const res=await fetch(`/bff/mobile/cases/${caseId}/upload-context`,{headers:jsonHeaders});const body=await res.json();const data=body.data;caseMeta.textContent=data.case.case_name;copy.textContent=data.submit_copy;}async function upload(){if(!fileInput.files[0]){status.textContent='请选择材料';return;}const form=new FormData();form.append('file',fileInput.files[0]);form.append('file_type',fileType.value);form.append('sensitivity_level',sensitivity.value);status.textContent='正在上传';const res=await fetch(`/api/cases/${caseId}/files`,{method:'POST',headers:baseHeaders,body:form});status.textContent=res.ok?'材料已收到，整理完成后会通知你。':'上传失败，请稍后重试';}load();</script></body></html>"""